"use client";

import { useAuth } from "~/lib/firebase/AuthContext";
import { collection, query, where, orderBy, Timestamp, onSnapshot } from "firebase/firestore";
import { db } from "~/lib/firebase/config";
import Link from "next/link";
import { useEffect, useState, useMemo, useCallback, useRef } from "react";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import { isSameDay, getDateString, toDate } from "~/lib/dateUtils";
import { useOwnerDebts } from "~/hooks/useOwnerDebts";
import { useOwnerRealtimePayments } from "~/hooks/useOwnerRealtimePayments";
import { MONTHS_IT, MONTHS_SHORT_IT } from "~/lib/payments/debtManager";
import type { MonthDebt } from "~/lib/payments/debtManager";

// ═══ BACKGROUND IMAGES ═══
const BG_SLIDE_1 = "data:image/jpeg;base64,";
const BG_SLIDE_2 = "data:image/jpeg;base64,";

// ═══ PROPERTY COLORS ═══
const PROP_COLORS = [
  { main: "#6366f1", light: "#818cf8", gradient: "linear-gradient(135deg,#6366f1,#4f46e5)" },
  { main: "#8b5cf6", light: "#a78bfa", gradient: "linear-gradient(135deg,#8b5cf6,#7c3aed)" },
  { main: "#ec4899", light: "#f472b6", gradient: "linear-gradient(135deg,#ec4899,#db2777)" },
  { main: "#f59e0b", light: "#fbbf24", gradient: "linear-gradient(135deg,#f59e0b,#d97706)" },
  { main: "#14b8a6", light: "#2dd4bf", gradient: "linear-gradient(135deg,#14b8a6,#0d9488)" },
  { main: "#06b6d4", light: "#22d3ee", gradient: "linear-gradient(135deg,#06b6d4,#0891b2)" },
  { main: "#f43f5e", light: "#fb7185", gradient: "linear-gradient(135deg,#f43f5e,#e11d48)" },
  { main: "#64748b", light: "#94a3b8", gradient: "linear-gradient(135deg,#64748b,#475569)" },
];

// ═══ CACHE ═══
const CACHE_KEY = 'proprietario_dashboard_v2_cache';
let cachedDashboardData: any = null; // Module-level cache: survives remounts

function getFromCache(): any {
  if (cachedDashboardData) return cachedDashboardData;
  if (typeof window === "undefined") return null;
  try { const c = localStorage.getItem(CACHE_KEY); return c ? JSON.parse(c) : null; } catch { return null; }
}
function saveToCache(data: any): void {
  cachedDashboardData = data; // Always save to module-level cache
  if (typeof window === "undefined") return;
  try { localStorage.setItem(CACHE_KEY, JSON.stringify(data)); } catch {}
}

export default function ProprietarioDashboard() {
  const { user } = useAuth();
  const today = new Date();
  const [data, setData] = useState<any>(() => getFromCache());
  const balance = useOwnerDebts(user?.id);

  // Hook pagamenti per slide 2 (riepilogo mese corrente)
  const currentMonthNum = today.getMonth() + 1;
  const currentYearNum = today.getFullYear();
  const prevMonthNum = currentMonthNum === 1 ? 12 : currentMonthNum - 1;
  const prevYearNum = currentMonthNum === 1 ? currentYearNum - 1 : currentYearNum;
  const paymentsCurrentMonth = useOwnerRealtimePayments(user?.id, currentMonthNum, currentYearNum);
  const paymentsPrevMonth = useOwnerRealtimePayments(user?.id, prevMonthNum, prevYearNum);

  const [currentSlide, setCurrentSlide] = useState(0);
  const [sliderReady, setSliderReady] = useState(false);
  const slideTimer = useRef<NodeJS.Timeout | null>(null);
  const touchStart = useRef(0);
  const touchDiff = useRef(0);

  const firstName = user?.name?.split(' ')[0] || 'Utente';
  const currentMonthName = today.toLocaleDateString("it-IT", { month: "long" });
  const currentMonthNameCap = currentMonthName.charAt(0).toUpperCase() + currentMonthName.slice(1);

  // ═══ GREETING ═══
  const greeting = useMemo(() => {
    const h = today.getHours();
    if (h < 12) return "Buongiorno";
    if (h < 18) return "Buon pomeriggio";
    return "Buonasera";
  }, []);

  // ═══ SLIDE AUTO-PLAY ═══
  const startAutoSlide = useCallback(() => {
    if (slideTimer.current) clearInterval(slideTimer.current);
    slideTimer.current = setInterval(() => setCurrentSlide(p => (p + 1) % 2), 5000);
  }, []);

  useEffect(() => {
    startAutoSlide();
    // Abilita transizioni dopo il primo render per evitare flash della slide 2
    requestAnimationFrame(() => { setSliderReady(true); });
    return () => { if (slideTimer.current) clearInterval(slideTimer.current); };
  }, [startAutoSlide]);

  const goToSlide = (i: number) => { setCurrentSlide(i); startAutoSlide(); };

  // ═══ REALTIME DATA ═══
  useEffect(() => {
    if (!user?.id) return;
    let propertiesData: any[] = [];
    let allCleaningsData: any[] = [];
    let ordersData: any[] = [];
    let loadedCount = 0;

    const updateDashboard = () => {
      if (loadedCount < 3) return;
      const propertyIds = propertiesData.map((p: any) => p.id);
      const myCleanings = allCleaningsData.filter((c: any) => propertyIds.includes(c.propertyId));
      const myOrders = ordersData.filter((o: any) => propertyIds.includes(o.propertyId));

      const todayStart = new Date(); todayStart.setHours(0, 0, 0, 0);
      const weekStart = new Date(); weekStart.setDate(weekStart.getDate() - weekStart.getDay() + 1); weekStart.setHours(0, 0, 0, 0);
      const weekEnd = new Date(weekStart); weekEnd.setDate(weekEnd.getDate() + 6); weekEnd.setHours(23, 59, 59, 999);
      const monthStart = new Date(today.getFullYear(), today.getMonth(), 1);
      const monthEnd = new Date(today.getFullYear(), today.getMonth() + 1, 0, 23, 59, 59, 999);

      // Previous month
      const prevMonthStart = new Date(today.getFullYear(), today.getMonth() - 1, 1);
      const prevMonthEnd = new Date(today.getFullYear(), today.getMonth(), 0, 23, 59, 59, 999);
      const prevMonthName = prevMonthStart.toLocaleDateString("it-IT", { month: "long" });

      const cleaningsMonth = myCleanings.filter((c: any) => { const d = c.scheduledDate?.toDate?.(); return d && d >= monthStart && d <= monthEnd; });
      const completedMonth = cleaningsMonth.filter((c: any) => c.status === "COMPLETED");
      const cleaningsWeek = myCleanings.filter((c: any) => { const d = c.scheduledDate?.toDate?.(); return d && d >= weekStart && d <= weekEnd; });
      const cleaningsPrevMonth = myCleanings.filter((c: any) => { const d = c.scheduledDate?.toDate?.(); return d && d >= prevMonthStart && d <= prevMonthEnd && c.status === "COMPLETED"; });

      // Spese mese corrente e mese scorso (pulizie)
      const spesaPulizieMonth = completedMonth.reduce((s: number, c: any) => s + (c.priceOverride ?? c.price ?? 0), 0);
      const spesaPuliziePrev = cleaningsPrevMonth.reduce((s: number, c: any) => s + (c.priceOverride ?? c.price ?? 0), 0);

      // Ordini biancheria mese corrente e scorso
      const ordersMonth = myOrders.filter((o: any) => {
        if (o.status !== "DELIVERED") return false;
        const d = o.deliveredAt?.toDate?.() || o.scheduledDate?.toDate?.() || o.createdAt?.toDate?.();
        return d && d >= monthStart && d <= monthEnd;
      });
      const ordersPrev = myOrders.filter((o: any) => {
        if (o.status !== "DELIVERED") return false;
        const d = o.deliveredAt?.toDate?.() || o.scheduledDate?.toDate?.() || o.createdAt?.toDate?.();
        return d && d >= prevMonthStart && d <= prevMonthEnd;
      });

      const calcOrderTotal = (o: any) => {
        if (o.totalPriceOverride) return o.totalPriceOverride;
        let t = 0;
        if (o.items) o.items.forEach((i: any) => { t += (i.priceOverride ?? i.price ?? 0) * (i.quantity || 1); });
        return t;
      };

      const spesaBiancheriaMonth = ordersMonth.reduce((s: number, o: any) => s + calcOrderTotal(o), 0);
      const spesaBiancheriaPrev = ordersPrev.reduce((s: number, o: any) => s + calcOrderTotal(o), 0);
      const spesaTotaleMonth = spesaPulizieMonth + spesaBiancheriaMonth;
      const spesaTotalePrev = spesaPuliziePrev + spesaBiancheriaPrev;
      const serviziMonth = completedMonth.length + ordersMonth.length;

      // Spesa per proprietà
      const propExpenses = propertiesData
        .filter((p: any) => p.status === "ACTIVE")
        .map((p: any) => {
          const pCleanings = completedMonth.filter((c: any) => c.propertyId === p.id);
          const pOrders = ordersMonth.filter((o: any) => o.propertyId === p.id);
          const spesaPul = pCleanings.reduce((s: number, c: any) => s + (c.priceOverride ?? c.price ?? 0), 0);
          const spesaBian = pOrders.reduce((s: number, o: any) => s + calcOrderTotal(o), 0);
          return {
            id: p.id, name: p.name || "Proprietà", imageUrl: p.imageUrl || null,
            cleanings: pCleanings.length, orders: pOrders.length,
            total: spesaPul + spesaBian,
          };
        })
        .filter((p: any) => p.total > 0)
        .sort((a: any, b: any) => b.total - a.total);

      // Weekly chart
      const daysOfWeek = ['Lun', 'Mar', 'Mer', 'Gio', 'Ven', 'Sab', 'Dom'];
      const weeklyChartData = daysOfWeek.map((day, index) => {
        const dayDate = new Date(weekStart); dayDate.setDate(dayDate.getDate() + index);
        const count = myCleanings.filter((c: any) => isSameDay(c.scheduledDate?.toDate?.(), dayDate)).length;
        return { day, servizi: count };
      });
      const weekTotal = weeklyChartData.reduce((s, d) => s + d.servizi, 0);

      // Previous week total
      const prevWeekStart = new Date(weekStart); prevWeekStart.setDate(prevWeekStart.getDate() - 7);
      const prevWeekEnd = new Date(prevWeekStart); prevWeekEnd.setDate(prevWeekEnd.getDate() + 6); prevWeekEnd.setHours(23, 59, 59, 999);
      const prevWeekTotal = myCleanings.filter((c: any) => { const d = c.scheduledDate?.toDate?.(); return d && d >= prevWeekStart && d <= prevWeekEnd; }).length;

      // 6-month expense data
      const monthlyExpenses: { month: string; monthShort: string; pulizie: number; biancheria: number; total: number; isCurrent: boolean }[] = [];
      for (let i = 5; i >= 0; i--) {
        const mDate = new Date(today.getFullYear(), today.getMonth() - i, 1);
        const mEnd = new Date(mDate.getFullYear(), mDate.getMonth() + 1, 0, 23, 59, 59, 999);
        const mCleanings = myCleanings.filter((c: any) => {
          if (c.status !== "COMPLETED") return false;
          const d = c.scheduledDate?.toDate?.();
          return d && d >= mDate && d <= mEnd;
        });
        const mOrders = myOrders.filter((o: any) => {
          if (o.status !== "DELIVERED") return false;
          const d = o.deliveredAt?.toDate?.() || o.scheduledDate?.toDate?.() || o.createdAt?.toDate?.();
          return d && d >= mDate && d <= mEnd;
        });
        const pul = mCleanings.reduce((s: number, c: any) => s + (c.priceOverride ?? c.price ?? 0), 0);
        const bia = mOrders.reduce((s: number, o: any) => s + calcOrderTotal(o), 0);
        monthlyExpenses.push({
          month: MONTHS_IT[mDate.getMonth()],
          monthShort: MONTHS_SHORT_IT[mDate.getMonth()],
          pulizie: pul, biancheria: bia, total: pul + bia,
          isCurrent: i === 0,
        });
      }

      const newData = {
        properties: propertiesData.filter((p: any) => p.status === "ACTIVE").length,
        pendingProperties: propertiesData.filter((p: any) => p.status === "PENDING").length,
        spesaPulizieMonth, spesaBiancheriaMonth, spesaTotaleMonth, serviziMonth,
        spesaTotalePrev, prevMonthName,
        propExpenses, weeklyChartData, weekTotal, prevWeekTotal,
        monthlyExpenses,
        cleaningsWeekCount: cleaningsWeek.length,
      };
      setData(newData);
      saveToCache(newData);
    };

    const checkAndUpdate = () => { loadedCount++; if (loadedCount >= 3) updateDashboard(); };

    const unsubProperties = onSnapshot(query(collection(db, "properties"), where("ownerId", "==", user.id)), (snapshot) => {
      propertiesData = snapshot.docs.map(doc => ({ id: doc.id, ...(doc.data() as Record<string, any>) }));
      if (loadedCount >= 3) updateDashboard(); else checkAndUpdate();
    });

    const sixMonthsAgo = new Date(today.getFullYear(), today.getMonth() - 5, 1);
    const nextMonth = new Date(today.getFullYear(), today.getMonth() + 2, 0);

    const unsubCleanings = onSnapshot(query(collection(db, "cleanings"), where("scheduledDate", ">=", Timestamp.fromDate(sixMonthsAgo)), where("scheduledDate", "<=", Timestamp.fromDate(nextMonth))), (snapshot) => {
      allCleaningsData = snapshot.docs.map(doc => ({ id: doc.id, ...(doc.data() as Record<string, any>) }));
      if (loadedCount >= 3) updateDashboard(); else checkAndUpdate();
    });

    const unsubOrders = onSnapshot(collection(db, "orders"), (snapshot) => {
      ordersData = snapshot.docs.map(doc => ({ id: doc.id, ...(doc.data() as Record<string, any>) }));
      if (loadedCount >= 3) updateDashboard(); else checkAndUpdate();
    });

    return () => { unsubProperties(); unsubCleanings(); unsubOrders(); };
  }, [user?.id]);

  // ═══ DERIVED DATA ═══
  const properties = data?.properties || 0;
  const pendingProperties = data?.pendingProperties || 0;

  // Dati dal hook pagamenti (coerenti con pagina pagamenti)
  const spesaPulizieMonth = paymentsCurrentMonth.stats?.cleaningsTotal || 0;
  const spesaBiancheriaMonth = (paymentsCurrentMonth.stats?.ordersTotal || 0) + (paymentsCurrentMonth.stats?.kitCortesiaTotal || 0) + (paymentsCurrentMonth.stats?.serviziExtraTotal || 0);
  const spesaTotaleMonth = paymentsCurrentMonth.stats?.totaleCalcolato || 0;
  const serviziMonth = (paymentsCurrentMonth.stats?.cleaningsCount || 0) + (paymentsCurrentMonth.stats?.ordersCount || 0) + (paymentsCurrentMonth.stats?.kitCortesiaCount || 0) + (paymentsCurrentMonth.stats?.serviziExtraCount || 0);
  const spesaTotalePrev = paymentsPrevMonth.stats?.totaleCalcolato || 0;

  const prevMonthName = data?.prevMonthName || "";
  const propExpenses: any[] = paymentsCurrentMonth.stats?.statsByProperty?.map(p => ({
    id: p.propertyId,
    name: p.propertyName,
    imageUrl: p.propertyImage || null,
    cleanings: p.cleaningsCount,
    orders: p.ordersCount,
    total: p.total,
  })) || data?.propExpenses || [];
  const weeklyChartData: any[] = data?.weeklyChartData || [];
  const weekTotal = data?.weekTotal || 0;
  const prevWeekTotal = data?.prevWeekTotal || 0;
  const monthlyExpenses: any[] = data?.monthlyExpenses || [];

  // Percentuale differenza mese scorso
  const prevMonthNameCap = prevMonthName ? prevMonthName.charAt(0).toUpperCase() + prevMonthName.slice(1) : "";
  const spesaDiffPct = spesaTotalePrev > 0 ? Math.round(((spesaTotaleMonth - spesaTotalePrev) / spesaTotalePrev) * 100) : 0;
  const weekDiff = weekTotal - prevWeekTotal;

  // Donut per proprietà
  const propTotal = propExpenses.reduce((s: number, p: any) => s + p.total, 0) || 1;
  const donutSegments = useMemo(() => {
    let offset = 25;
    return propExpenses.map((p: any, i: number) => {
      const pct = (p.total / propTotal) * 100;
      const seg = { offset, pct, color: PROP_COLORS[i % PROP_COLORS.length].main };
      offset -= pct;
      return seg;
    });
  }, [propExpenses, propTotal]);

  // 6-month chart max
  const maxMonthly = Math.max(...monthlyExpenses.map(m => m.total), 1);

  // Payment banner state — dati da useOwnerDebts (stessa logica di pagina pagamenti)
  const bannerState = balance.countScaduti > 0 ? "danger" : balance.countWarning > 0 ? "warning" : balance.hasDebts ? "normal" : "ok";
  const nearestDebt = balance.debts.length > 0 ? balance.debts.reduce((n: MonthDebt, d: MonthDebt) => (d.giorniAllaScadenza < n.giorniAllaScadenza ? d : n), balance.debts[0]) : null;

  // ═══ SKELETON ═══
  if (!data) {
    return (
      <div className="min-h-screen bg-slate-50 p-4">
        <div className="animate-pulse space-y-4">
          <div className="h-48 bg-gray-200 rounded-2xl" />
          <div className="grid grid-cols-2 gap-3">{[1,2].map(i => <div key={i} className="h-24 bg-gray-200 rounded-xl" />)}</div>
          <div className="h-40 bg-gray-200 rounded-xl" />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <style>{`
        @keyframes db-aurora{0%,100%{transform:translate(0,0)}33%{transform:translate(2%,-1.5%)}66%{transform:translate(-1.5%,2%)}}
        @keyframes db-blink{0%,100%{opacity:1}50%{opacity:.3}}
        @keyframes db-slideFade{0%{opacity:0;transform:translateY(5px)}100%{opacity:1;transform:translateY(0)}}
        .db-aurora::before{content:'';position:absolute;width:280%;height:280%;top:-90%;left:-90%;background:radial-gradient(ellipse 400px 300px at 15% 45%,rgba(99,102,241,.28) 0%,transparent 70%),radial-gradient(ellipse 350px 250px at 75% 35%,rgba(139,92,246,.18) 0%,transparent 70%),radial-gradient(ellipse 250px 180px at 50% 85%,rgba(59,130,246,.12) 0%,transparent 70%);animation:db-aurora 16s ease-in-out infinite}
        .db-grid-bg{display:none}
        .db-prop-scroll::-webkit-scrollbar{width:2px}
        .db-prop-scroll::-webkit-scrollbar-thumb{background:#e2e8f0;border-radius:2px}
      `}</style>

      {/* ═══ BANNER ═══ */}
      <div className="relative overflow-hidden" style={{ padding: "16px 16px 22px", background: "#0b0b18" }}>
        {/* BG Photos */}
        <div className="absolute inset-0 bg-cover bg-center transition-opacity duration-800" style={{ backgroundImage: `url(${BG_SLIDE_1})`, opacity: currentSlide === 0 ? 0.7 : 0 }} />
        {sliderReady && <div className="absolute inset-0 bg-cover bg-center transition-opacity duration-800" style={{ backgroundImage: `url(${BG_SLIDE_2})`, opacity: currentSlide === 1 ? 0.7 : 0 }} />}
        <div className="absolute inset-0" style={{ background: "linear-gradient(180deg,rgba(11,11,24,0.5) 0%,rgba(11,11,24,0.88) 100%)" }} />
        <div className="db-aurora absolute inset-0 overflow-hidden" style={{ opacity: 0.3 }} />
        <div className="db-grid-bg absolute inset-0" />

        <div className="relative z-10">
          {/* Header */}
          <div className="flex items-center justify-between mb-3.5">
            <div>
              <div className="text-[15px] font-bold text-white" style={{ letterSpacing: "-0.3px", textShadow: "0 1px 4px rgba(0,0,0,0.3)" }}>
                {greeting}, <span style={{ background: "linear-gradient(135deg,#c7d2fe,#a5b4fc)", WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}>{firstName}</span>
              </div>
              <div className="text-[10px] font-medium" style={{ color: "rgba(255,255,255,0.55)", marginTop: 1 }}>
                {properties} proprietà attive · {currentMonthNameCap} {today.getFullYear()}
              </div>
            </div>
            <div className="flex items-center gap-[5px]">
              <div className="w-[5px] h-[5px] rounded-full" style={{ background: "#10b981", boxShadow: "0 0 6px rgba(16,185,129,0.5)", animation: "db-blink 2s ease infinite" }} />
              <span className="text-[9px] font-bold uppercase" style={{ color: "rgba(255,255,255,0.55)", letterSpacing: "1.5px" }}>Live</span>
            </div>
          </div>

          {/* SLIDES */}
          <div
            className="relative overflow-hidden"
            onTouchStart={(e) => { touchStart.current = e.touches[0].clientX; if (slideTimer.current) clearInterval(slideTimer.current); }}
            onTouchMove={(e) => { touchDiff.current = e.touches[0].clientX - touchStart.current; }}
            onTouchEnd={() => {
              if (Math.abs(touchDiff.current) > 50) {
                if (touchDiff.current < 0 && currentSlide < 1) goToSlide(1);
                else if (touchDiff.current > 0 && currentSlide > 0) goToSlide(0);
              }
              touchDiff.current = 0; startAutoSlide();
            }}
          >
            <div className={`flex${sliderReady ? " transition-transform duration-600" : ""}`} style={{ transform: `translateX(-${currentSlide * 100}%)`, transitionTimingFunction: "cubic-bezier(0.22,1,0.36,1)" }}>

              {/* ═══ SLIDE 1: PAGAMENTI ═══ */}
              <div className="min-w-full">
                <div
                  className="rounded-[14px] flex flex-col"
                  style={{
                    minHeight: 138, padding: "14px 16px",
                    backdropFilter: "blur(16px)",
                    background: bannerState === "danger" ? "rgba(239,68,68,0.08)" : bannerState === "warning" ? "rgba(245,158,11,0.08)" : bannerState === "ok" ? "rgba(16,185,129,0.06)" : "rgba(99,102,241,0.06)",
                    border: `1px solid ${bannerState === "danger" ? "rgba(239,68,68,0.15)" : bannerState === "warning" ? "rgba(245,158,11,0.15)" : bannerState === "ok" ? "rgba(16,185,129,0.12)" : "rgba(99,102,241,0.12)"}`,
                    opacity: balance.isLoading ? 0 : 1,
                    transition: "opacity 0.5s ease",
                  }}
                >
                  {/* Tag */}
                  <div className="flex items-center gap-[5px] mb-2" style={{ fontSize: 9, fontWeight: 700, textTransform: "uppercase", letterSpacing: "1.5px", color: bannerState === "danger" ? "#f87171" : bannerState === "warning" ? "#fbbf24" : bannerState === "ok" ? "#34d399" : "#a5b4fc" }}>
                    {bannerState === "ok" ? (
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M22 11.08V12a10 10 0 11-5.93-9.14"/><path d="M22 4L12 14.01l-3-3"/></svg>
                    ) : bannerState === "warning" ? (
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><path d="M12 9v4M12 17h.01"/></svg>
                    ) : (
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><path d="M12 8v4M12 16h.01"/></svg>
                    )}
                    {bannerState === "ok" ? "Pagamenti in regola" : bannerState === "warning" ? "Pagamento in scadenza" : "Situazione pagamenti"}
                  </div>

                  {/* Main row */}
                  <div className="flex items-start justify-between gap-3 flex-1">
                    <div className="flex-1 min-w-0">
                      <div className="text-[28px] font-extrabold text-white" style={{ letterSpacing: -1, lineHeight: 1 }}>
                        {bannerState === "ok" ? (
                          <span style={{ color: "#34d399" }}>€0<span className="text-[15px] opacity-50">,00</span></span>
                        ) : (
                          <>€{balance.totalDebt % 1 === 0 ? Math.round(balance.totalDebt) : balance.totalDebt.toFixed(2).replace('.', ',')}</>
                        )}
                      </div>
                      <div className="flex items-center gap-[5px] mt-1.5" style={{ fontSize: 9, color: "rgba(255,255,255,0.5)", fontWeight: 500 }}>
                        <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.4)" strokeWidth="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
                        {bannerState === "ok" ? (
                          <span>Nessun pagamento in sospeso</span>
                        ) : nearestDebt ? (
                          <span>Scadenza: <strong style={{ color: "rgba(255,255,255,0.75)" }}>{nearestDebt.scadenza.toLocaleDateString("it-IT", { day: "numeric", month: "long", year: "numeric" })}</strong></span>
                        ) : null}
                      </div>
                    </div>
                    <div className="flex flex-col gap-1 flex-shrink-0 mt-2">
                      {bannerState === "ok" ? (
                        <div className="inline-flex items-center gap-1 text-[9px] font-semibold rounded-[6px] px-2 py-[3px]" style={{ background: "rgba(16,185,129,0.15)", color: "#6ee7b7" }}>
                          <span className="w-[5px] h-[5px] rounded-full inline-block" style={{ background: "#10b981" }} />Tutto saldato
                        </div>
                      ) : (
                        <>
                          {balance.countScaduti > 0 && (
                            <div className="inline-flex items-center gap-1 text-[9px] font-semibold rounded-[6px] px-2 py-[3px]" style={{ background: "rgba(239,68,68,0.15)", color: "#fca5a5" }}>
                              <span className="w-[5px] h-[5px] rounded-full inline-block" style={{ background: "#ef4444" }} />{balance.countScaduti} mesi scaduti
                            </div>
                          )}
                          {balance.countWarning > 0 && (
                            <div className="inline-flex items-center gap-1 text-[9px] font-semibold rounded-[6px] px-2 py-[3px]" style={{ background: "rgba(245,158,11,0.15)", color: "#fcd34d" }}>
                              <span className="w-[5px] h-[5px] rounded-full inline-block" style={{ background: "#f59e0b" }} />{balance.countWarning} in scadenza
                            </div>
                          )}
                          {balance.countDaPagare > 0 && (
                            <div className="inline-flex items-center gap-1 text-[9px] font-semibold rounded-[6px] px-2 py-[3px]" style={{ background: "rgba(99,102,241,0.15)", color: "#c7d2fe" }}>
                              <span className="w-[5px] h-[5px] rounded-full inline-block" style={{ background: "#6366f1" }} />{balance.countDaPagare} da pagare
                            </div>
                          )}
                        </>
                      )}
                    </div>
                  </div>

                  {/* Progress bar */}
                  <div className="w-full h-1 rounded-sm overflow-hidden mt-2.5" style={{ background: "rgba(255,255,255,0.08)" }}>
                    <div className="h-full rounded-sm" style={{
                      width: bannerState === "ok" ? "100%" : balance.debts.length > 0 ? `${Math.max(5, (balance.debts.reduce((s, d) => s + d.totalePagato, 0) / Math.max(1, balance.debts.reduce((s, d) => s + d.totaleServizi, 0))) * 100)}%` : "0%",
                      background: bannerState === "danger" ? "linear-gradient(90deg,#ef4444,#f87171)" : bannerState === "warning" ? "linear-gradient(90deg,#f59e0b,#fbbf24)" : "linear-gradient(90deg,#10b981,#34d399)",
                    }} />
                  </div>
                </div>
              </div>

              {/* ═══ SLIDE 2: RIEPILOGO MESE ═══ */}
              <div className="min-w-full">
                <div className="rounded-[14px] flex flex-col" style={{ minHeight: 138, padding: "14px 16px", backdropFilter: "blur(16px)", background: "rgba(0,0,0,0.25)", border: "1px solid rgba(255,255,255,0.08)", opacity: balance.isLoading ? 0 : 1, transition: "opacity 0.5s ease" }}>
                  <div className="flex items-center gap-[5px] mb-2" style={{ fontSize: 9, fontWeight: 700, textTransform: "uppercase", letterSpacing: "1.5px", color: "#a5b4fc" }}>
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/></svg>
                    {currentMonthNameCap} {today.getFullYear()}
                    {spesaDiffPct !== 0 && (
                      <div className="ml-auto inline-flex items-center gap-[3px] text-[10px] font-bold rounded-[6px] px-[7px] py-[2px]" style={{ background: spesaDiffPct > 0 ? "rgba(239,68,68,0.15)" : "rgba(16,185,129,0.15)", color: spesaDiffPct > 0 ? "#f87171" : "#34d399" }}>
                        <svg width="9" height="9" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d={spesaDiffPct > 0 ? "M7 7l5 5 5-5" : "M7 17l5-5 5 5"}/></svg>
                        {spesaDiffPct > 0 ? "+" : ""}{spesaDiffPct}% vs {prevMonthNameCap?.slice(0, 3)}
                      </div>
                    )}
                  </div>

                  <div className="grid grid-cols-3 gap-1.5">
                    <div className="rounded-[10px] p-2 text-center" style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.06)" }}>
                      <div className="text-[20px] font-extrabold" style={{ color: "#a5b4fc", lineHeight: 1 }}>€{spesaPulizieMonth > 999 ? `${(spesaPulizieMonth/1000).toFixed(1)}k` : Math.round(spesaPulizieMonth)}</div>
                      <div className="text-[8px] font-semibold uppercase mt-[3px]" style={{ color: "rgba(165,180,252,0.6)", letterSpacing: "0.5px" }}>Pulizie</div>
                    </div>
                    <div className="rounded-[10px] p-2 text-center" style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.06)" }}>
                      <div className="text-[20px] font-extrabold" style={{ color: "#c4b5fd", lineHeight: 1 }}>€{spesaBiancheriaMonth > 999 ? `${(spesaBiancheriaMonth/1000).toFixed(1)}k` : Math.round(spesaBiancheriaMonth)}</div>
                      <div className="text-[8px] font-semibold uppercase mt-[3px]" style={{ color: "rgba(196,181,253,0.6)", letterSpacing: "0.5px" }}>Biancheria</div>
                    </div>
                    <div className="rounded-[10px] p-2 text-center" style={{ background: "rgba(255,255,255,0.04)", border: "1px solid rgba(255,255,255,0.06)" }}>
                      <div className="text-[20px] font-extrabold" style={{ color: "#34d399", lineHeight: 1 }}>{serviziMonth}</div>
                      <div className="text-[8px] font-semibold uppercase mt-[3px]" style={{ color: "rgba(52,211,153,0.6)", letterSpacing: "0.5px" }}>Servizi</div>
                    </div>
                  </div>

                  <div className="flex items-center justify-between mt-auto pt-2" style={{ borderTop: "1px solid rgba(255,255,255,0.06)" }}>
                    <div>
                      <div className="text-[9px] font-medium" style={{ color: "rgba(255,255,255,0.4)" }}>Totale servizi</div>
                      <div className="flex items-baseline gap-[5px] mt-[1px]">
                        <span className="text-[11px] font-medium" style={{ color: "rgba(255,255,255,0.5)" }}>{data?.serviziMonth || 0} servizi</span>
                      </div>
                    </div>
                    <div className="text-right">
                      <div className="text-[9px] font-medium" style={{ color: "rgba(255,255,255,0.4)" }}>Spesa mese</div>
                      <div className="text-[18px] font-extrabold text-white" style={{ letterSpacing: -0.5, marginTop: 1 }}>€{spesaTotaleMonth > 999 ? `${(spesaTotaleMonth/1000).toFixed(1)}k` : Math.round(spesaTotaleMonth)}</div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Dots */}
          <div className="flex justify-center gap-1.5 mt-2.5">
            {[0, 1].map(i => (
              <button key={i} onClick={() => goToSlide(i)} className="transition-all duration-400" style={{ width: currentSlide === i ? 20 : 6, height: 6, borderRadius: currentSlide === i ? 3 : "50%", background: currentSlide === i ? "rgba(255,255,255,0.85)" : "rgba(255,255,255,0.25)", border: "none", cursor: "pointer", padding: 0 }} />
            ))}
          </div>
        </div>
      </div>

      {/* ═══ CONTENT ═══ */}
      <div className="px-4 pt-3 space-y-3.5">

        {/* KPI Row */}
        <div className="grid grid-cols-2 gap-2.5">
          <div className="bg-white rounded-2xl p-3.5 shadow-sm" style={{ border: "1px solid rgba(0,0,0,0.03)" }}>
            <div className="w-[34px] h-[34px] rounded-[10px] flex items-center justify-center mb-2" style={{ background: "#eef2ff" }}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#6366f1" strokeWidth="2" strokeLinecap="round"><path d="M3 9l9-7 9 7v11a2 2 0 01-2 2H5a2 2 0 01-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>
            </div>
            <div className="text-[24px] font-extrabold text-slate-900" style={{ letterSpacing: -0.5, lineHeight: 1 }}>{properties}</div>
            <div className="text-[11px] text-slate-400 font-medium mt-[3px]">Proprietà attive</div>
            {pendingProperties > 0 && <div className="text-[10px] font-semibold text-amber-600 mt-1">+{pendingProperties} in attesa</div>}
          </div>
          <div className="bg-white rounded-2xl p-3.5 shadow-sm" style={{ border: "1px solid rgba(0,0,0,0.03)" }}>
            <div className="w-[34px] h-[34px] rounded-[10px] flex items-center justify-center mb-2" style={{ background: "#f0fdf4" }}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#16a34a" strokeWidth="2" strokeLinecap="round"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/></svg>
            </div>
            <div className="text-[24px] font-extrabold text-slate-900" style={{ letterSpacing: -0.5, lineHeight: 1 }}>€{spesaTotalePrev > 999 ? `${(spesaTotalePrev/1000).toFixed(1)}k` : Math.round(spesaTotalePrev)}</div>
            <div className="text-[11px] text-slate-400 font-medium mt-[3px]">Spesa {prevMonthNameCap}</div>
            {spesaDiffPct !== 0 && (
              <div className="inline-flex items-center gap-[3px] text-[10px] font-semibold mt-1 px-1.5 py-[2px] rounded" style={{ background: spesaDiffPct > 0 ? "#fef2f2" : "#ecfdf5", color: spesaDiffPct > 0 ? "#dc2626" : "#059669" }}>
                <svg width="8" height="8" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3"><path d={spesaDiffPct > 0 ? "M7 7l5 5 5-5" : "M7 17l5-5 5 5"}/></svg>
                {spesaDiffPct > 0 ? "+" : ""}{spesaDiffPct}% vs {currentMonthNameCap?.slice(0, 3)}
              </div>
            )}
          </div>
        </div>

        {/* Weekly chart */}
        <div className="bg-white rounded-2xl p-3.5 shadow-sm" style={{ border: "1px solid rgba(0,0,0,0.03)" }}>
          <div className="flex items-center justify-between mb-3">
            <div>
              <div className="text-[14px] font-bold text-slate-900">Questa settimana</div>
              <div className="text-[11px] text-slate-400 font-medium mt-[1px]">{weekTotal} servizi programmati</div>
            </div>
            {weekDiff !== 0 && (
              <div className="inline-flex items-center gap-[3px] text-[10px] font-bold rounded-[6px] px-[7px] py-[2px]" style={{ background: weekDiff > 0 ? "#ecfdf5" : "#fef2f2", color: weekDiff > 0 ? "#059669" : "#dc2626" }}>
                {weekDiff > 0 ? "+" : ""}{weekDiff} vs scorsa
              </div>
            )}
          </div>
          <div className="h-[120px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={weeklyChartData} barSize={28}>
                <XAxis dataKey="day" axisLine={false} tickLine={false} tick={{ fill: '#94a3b8', fontSize: 10, fontWeight: 600 }} />
                <YAxis hide />
                <Tooltip contentStyle={{ backgroundColor: '#1e293b', border: 'none', borderRadius: 8, color: '#fff', fontSize: 11 }} cursor={{ fill: 'rgba(99,102,241,0.06)' }} />
                <Bar dataKey="servizi" radius={[6, 6, 3, 3]}>
                  {weeklyChartData.map((_: any, index: number) => {
                    const dayIdx = today.getDay(); const adj = dayIdx === 0 ? 6 : dayIdx - 1;
                    const isPast = index < adj;
                    const isToday = index === adj;
                    return <Cell key={index} fill={isToday ? "#4f46e5" : isPast ? "#818cf8" : "#e2e8f0"} />;
                  })}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Spesa per proprietà — Variante C */}
        {propExpenses.length > 0 && (
          <div className="bg-white rounded-2xl p-3.5 shadow-sm" style={{ border: "1px solid rgba(0,0,0,0.03)" }}>
            <div className="flex items-center justify-between mb-3">
              <div>
                <div className="text-[14px] font-bold text-slate-900">Spesa per proprietà</div>
                <div className="text-[11px] text-slate-400 font-medium mt-[1px]">{currentMonthNameCap} {today.getFullYear()}</div>
              </div>
            </div>

            {/* Donut grande */}
            <div className="relative mx-auto mb-4" style={{ width: 130, height: 130 }}>
              <svg viewBox="0 0 42 42" width="130" height="130">
                <circle cx="21" cy="21" r="15.915" fill="none" stroke="#f1f5f9" strokeWidth="3" />
                {donutSegments.map((seg, i) => (
                  <circle key={i} cx="21" cy="21" r="15.915" fill="none" stroke={seg.color} strokeWidth="3" strokeDasharray={`${seg.pct} ${100 - seg.pct}`} strokeDashoffset={seg.offset} strokeLinecap="round" />
                ))}
              </svg>
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <div className="text-[18px] font-extrabold text-slate-900" style={{ lineHeight: 1 }}>€{spesaTotaleMonth > 999 ? `${(spesaTotaleMonth/1000).toFixed(1)}k` : Math.round(spesaTotaleMonth)}</div>
                <div className="text-[9px] text-slate-400 font-medium mt-[2px]">totale mese</div>
              </div>
            </div>

            {/* Lista proprietà */}
            <div className="flex flex-col gap-2">
              {propExpenses.map((p: any, i: number) => {
                const color = PROP_COLORS[i % PROP_COLORS.length];
                const pct = propTotal > 0 ? Math.round((p.total / propTotal) * 100) : 0;
                return (
                  <div key={p.id} className="flex items-center gap-2.5 rounded-xl p-2.5" style={{ background: "#f8fafc", border: "1px solid #f1f5f9" }}>
                    <div className="w-2.5 h-2.5 rounded-sm flex-shrink-0" style={{ background: color.main }} />
                    {p.imageUrl ? (
                      <img src={p.imageUrl} alt="" className="w-[38px] h-[38px] rounded-lg flex-shrink-0 object-cover" />
                    ) : (
                      <div className="w-[38px] h-[38px] rounded-lg flex-shrink-0 flex items-center justify-center text-white font-bold text-[13px]" style={{ background: color.gradient }}>{(p.name || "?")[0]}</div>
                    )}
                    <div className="flex-1 min-w-0">
                      <div className="text-[11px] font-semibold text-slate-900">{p.name}</div>
                      <div className="text-[9px] text-slate-400 mt-[1px]">{p.cleanings} pul · {p.orders} cons</div>
                    </div>
                    <div className="text-right flex-shrink-0">
                      <div className="text-[14px] font-extrabold text-slate-900">€{p.total % 1 === 0 ? Math.round(p.total) : p.total.toFixed(1)}</div>
                      <div className="text-[9px] text-slate-400 font-medium">{pct}%</div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Dettaglio pagamenti */}
        {balance.hasDebts && (
          <div className="bg-white rounded-2xl p-3.5 shadow-sm" style={{ border: "1px solid rgba(0,0,0,0.03)" }}>
            <div className="flex items-center justify-between mb-3">
              <div>
                <div className="text-[14px] font-bold text-slate-900">Dettaglio pagamenti</div>
                <div className="text-[11px] text-slate-400 font-medium mt-[1px]">Riepilogo mensile</div>
              </div>
              <div className="flex items-center gap-1.5">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#ef4444" strokeWidth="2" strokeLinecap="round"><path d="M12 2v20M17 5H9.5a3.5 3.5 0 000 7h5a3.5 3.5 0 010 7H6"/></svg>
                <span className="text-[18px] font-extrabold" style={{ color: bannerState === "danger" ? "#ef4444" : bannerState === "warning" ? "#d97706" : "#6366f1" }}>€{balance.totalDebt % 1 === 0 ? Math.round(balance.totalDebt) : balance.totalDebt.toFixed(2).replace('.', ',')}</span>
              </div>
            </div>

            {/* Summary pills */}
            <div className="flex gap-1.5 mb-3 flex-wrap">
              {balance.countScaduti > 0 && (
                <div className="flex items-center gap-1 text-[10px] font-semibold rounded-lg px-2.5 py-1" style={{ background: "#fef2f2", color: "#dc2626" }}>
                  <span className="w-1.5 h-1.5 rounded-full" style={{ background: "#ef4444" }} />{balance.countScaduti} scaduti · €{(() => { const v = balance.debts.filter(d => d.status === "SCADUTO").reduce((s, d) => s + d.saldo, 0); return v % 1 === 0 ? v : v.toFixed(2).replace(".", ","); })()}
                </div>
              )}
              {balance.countWarning > 0 && (
                <div className="flex items-center gap-1 text-[10px] font-semibold rounded-lg px-2.5 py-1" style={{ background: "#fffbeb", color: "#d97706" }}>
                  <span className="w-1.5 h-1.5 rounded-full" style={{ background: "#f59e0b" }} />{balance.countWarning} in scadenza · €{(() => { const v = balance.debts.filter(d => d.status === "WARNING").reduce((s, d) => s + d.saldo, 0); return v % 1 === 0 ? v : v.toFixed(2).replace(".", ","); })()}
                </div>
              )}
            </div>

            {/* Payment rows */}
            <div className="flex flex-col">
              {balance.debts.map((debt, i) => {
                const isScaduto = debt.status === "SCADUTO";
                const isWarning = debt.status === "WARNING";
                const statusColor = isScaduto ? "#ef4444" : isWarning ? "#d97706" : "#6366f1";
                const statusBg = isScaduto ? "#fef2f2" : isWarning ? "#fffbeb" : "#eef2ff";
                const statusLabel = isScaduto ? "Scaduto" : isWarning ? "In scadenza" : "Da pagare";
                const paidPct = debt.totaleServizi > 0 ? (debt.totalePagato / debt.totaleServizi) * 100 : 0;

                return (
                  <div key={`${debt.month}-${debt.year}`} className="flex items-center gap-3 py-2.5" style={{ borderBottom: i < balance.debts.length - 1 ? "1px solid #f8fafc" : "none" }}>
                    <div className="w-[3px] h-9 rounded-full flex-shrink-0" style={{ background: `linear-gradient(180deg,${statusColor},${statusColor}88)` }} />
                    <div className="w-[34px] h-[34px] rounded-[10px] flex-shrink-0 flex items-center justify-center" style={{ background: statusBg }}>
                      {isScaduto ? (
                        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={statusColor} strokeWidth="2" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><path d="M12 8v4M12 16h.01"/></svg>
                      ) : isWarning ? (
                        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={statusColor} strokeWidth="2" strokeLinecap="round"><path d="M10.29 3.86L1.82 18a2 2 0 001.71 3h16.94a2 2 0 001.71-3L13.71 3.86a2 2 0 00-3.42 0z"/><path d="M12 9v4M12 17h.01"/></svg>
                      ) : (
                        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke={statusColor} strokeWidth="2" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="text-[12px] font-semibold text-slate-900">{debt.monthName} {debt.year}</div>
                      <div className="text-[9px] text-slate-400 mt-[1px]">
                        {isScaduto ? `Scaduto da ${Math.abs(debt.giorniAllaScadenza)} giorni` : isWarning ? `Scade il ${debt.scadenza.toLocaleDateString("it-IT", { day: "numeric", month: "long" })}` : `Scade il ${debt.scadenza.toLocaleDateString("it-IT", { day: "numeric", month: "long" })}`}
                      </div>
                      <div className="w-full h-[3px] rounded-sm mt-1.5 overflow-hidden" style={{ background: "#f1f5f9" }}>
                        <div className="h-full rounded-sm" style={{ width: `${paidPct}%`, background: statusColor }} />
                      </div>
                    </div>
                    <div className="text-right flex-shrink-0">
                      <div className="text-[14px] font-extrabold" style={{ color: statusColor }}>€{debt.saldo % 1 === 0 ? debt.saldo : debt.saldo.toFixed(2).replace(".", ",")}</div>
                      <div className="text-[8px] font-semibold px-1.5 py-[2px] rounded mt-[2px] inline-block" style={{ background: statusBg, color: statusColor }}>{statusLabel}</div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Spesa ultimi 6 mesi */}
        {monthlyExpenses.length > 0 && (
          <div className="bg-white rounded-2xl p-3.5 shadow-sm" style={{ border: "1px solid rgba(0,0,0,0.03)" }}>
            <div className="flex items-center justify-between mb-3">
              <div>
                <div className="text-[14px] font-bold text-slate-900">Spesa ultimi 6 mesi</div>
                <div className="text-[11px] text-slate-400 font-medium mt-[1px]">Pulizie + biancheria</div>
              </div>
            </div>
            <div className="flex items-end gap-2" style={{ height: 120, paddingTop: 14 }}>
              {monthlyExpenses.map((m, i) => {
                const totalH = maxMonthly > 0 ? (m.total / maxMonthly) * 90 : 0;
                const pulH = m.total > 0 ? (m.pulizie / m.total) * totalH : 0;
                const biaH = totalH - pulH;
                return (
                  <div key={i} className="flex-1 flex flex-col items-center gap-[5px]">
                    <div className="w-full flex flex-col relative">
                      <span className="text-[9px] font-bold text-center mb-[2px]" style={{ color: m.isCurrent ? "#4f46e5" : "#475569" }}>
                        {m.total > 999 ? `€${(m.total/1000).toFixed(1)}k` : `€${Math.round(m.total)}`}
                      </span>
                      {biaH > 0 && (
                        <div style={{ height: biaH, borderRadius: "6px 6px 0 0", background: m.isCurrent ? "linear-gradient(180deg,#a78bfa,#8b5cf6)" : "linear-gradient(180deg,#c4b5fd,#a78bfa)", boxShadow: m.isCurrent ? "0 0 8px rgba(139,92,246,0.3)" : "none" }} />
                      )}
                      {pulH > 0 && (
                        <div style={{ height: pulH, borderRadius: biaH > 0 ? "0 0 3px 3px" : "6px 6px 3px 3px", background: m.isCurrent ? "linear-gradient(180deg,#6366f1,#4f46e5)" : "linear-gradient(180deg,#a5b4fc,#818cf8)", boxShadow: m.isCurrent ? "0 4px 12px rgba(99,102,241,0.3)" : "none" }} />
                      )}
                    </div>
                    <span className="text-[9px] font-semibold" style={{ color: m.isCurrent ? "#4f46e5" : "#94a3b8" }}>{m.monthShort}</span>
                  </div>
                );
              })}
            </div>
            <div className="flex items-center gap-3 mt-2.5">
              <div className="flex items-center gap-1 text-[10px] text-slate-500 font-medium"><div className="w-2 h-2 rounded-sm" style={{ background: "#6366f1" }} />Pulizie</div>
              <div className="flex items-center gap-1 text-[10px] text-slate-500 font-medium"><div className="w-2 h-2 rounded-sm" style={{ background: "#a78bfa" }} />Biancheria</div>
            </div>
          </div>
        )}

      </div>
    </div>
  );
}
